using Azure.Identity;
using Azure.ResourceManager;
using Azure.ResourceManager.Sql;
using Azure.ResourceManager.Sql.Models;

var armClient = new ArmClient(new DefaultAzureCredential());
var subscription = await armClient.GetDefaultSubscriptionAsync();
var resourceGroup = await subscription.GetResourceGroups()
    .GetAsync("azure-for-aspnet-rg");

// Create SQL server
var serverData = new SqlServerData(AzureLocation.EastUS)
{
    Administrators = new ServerExternalAdministratorProperties
    {
        AdministratorType = ServerExternalAdministratorType.ActiveDirectory,
        Login = "azure-admin",
        Sid = Guid.Parse("your-guid-here"),
        TenantId = Guid.Parse("your-tenant-guid-here"),
        AzureADOnlyAuthentication = true
    }
};

var serverLro = await resourceGroup.Value.GetSqlServers()
    .CreateOrUpdateAsync(WaitUntil.Completed, "aspnet-sql-server-001", serverData);
var server = serverLro.Value;

// Create database
var dbData = new SqlDatabaseData(AzureLocation.EastUS)
{
    Sku = new SqlSku("GP_S_Gen5_2")
};

var dbLro = await server.GetSqlDatabases()
    .CreateOrUpdateAsync(WaitUntil.Completed, "BlogDb", dbData);
var database = dbLro.Value;
Console.WriteLine($"Database {database.Data.Name} created");

var firewallRule = await server.GetSqlFirewallRules()
    .CreateOrUpdateAsync(
        WaitUntil.Completed,
        "AllowAzureServices",
        new SqlFirewallRuleData()
        {
            StartIpAddress = "0.0.0.0",
            EndIpAddress = "0.0.0.0"
        });
